#include "sa.h"

GeneralizedSuffixAutomaton::GeneralizedSuffixAutomaton() {
    st.clear();
    st.emplace_back(); // state 0 = initial
    st[0].link = -1;
    last = 0;
}

GeneralizedSuffixAutomaton::GeneralizedSuffixAutomaton(char* input_file) {
    std::ifstream f(input_file);
    int n;
    f >> n;
    st.resize(n);
    for (int i = 0; i < n; i++) {
        int m, k;
        f >> st[i].len >> st[i].link >> m >> k;
        st[i].next.reserve(m);
        for (int j = 0; j < m; j++) {
            int x, y;
            f >> x >> y;
            st[i].next.push_back({char(x), static_cast<uint32_t>(y)});
        }
        st[i].ids.resize(k);
        for (int j = 0; j < k; j++) {
            f >> st[i].ids[j];
        }
    }
    f.close();
}

GeneralizedSuffixAutomaton::~GeneralizedSuffixAutomaton() {
    if (deg) delete [] deg;
    if (reverse_next) delete [] reverse_next;
}

int GeneralizedSuffixAutomaton::size() {
    return st.size();
}

void GeneralizedSuffixAutomaton::clear() {
    st.clear();
    st.emplace_back();
    st[0].link = -1;
    last = 0;
}

int GeneralizedSuffixAutomaton::get_next(int state, char c) const {
    for (const auto& e : st[state].next) {
        if (e.c == c) return static_cast<int>(e.to);
    }
    return -1;
}

bool GeneralizedSuffixAutomaton::has_next(int state, char c) const {
    return get_next(state, c) != -1;
}

void GeneralizedSuffixAutomaton::set_next(int state, char c, uint32_t to) {
    for (auto& e : st[state].next) {
        if (e.c == c) {
            e.to = to;
            return;
        }
    }
    st[state].next.push_back({c, to});
}

void GeneralizedSuffixAutomaton::sa_extend(char c, uint32_t id) {
    int existing = get_next(last, c);
    if (existing != -1) {
        int x = existing;
        if (st[x].len == st[last].len + 1) {
            last = x;
        }
        else {
            // Clone st[last].next[c]
            int cur = (int)st.size();
            st.emplace_back();
            st[cur].len = st[last].len + 1;
            for (auto e : st[x].next) {
                st[cur].next.push_back(e);
            }
            st[cur].link = st[x].link;
            for (auto old_id : st[x].ids) { // copy ids
                st[cur].ids.emplace_back(old_id);
            }
            cloned_states.emplace_back(cur, x);
            affected_states.emplace_back(cur);
            int p = last;
            while (p != -1 && get_next(p, c) == x) {
                set_next(p, c, cur);
                p = st[p].link;
            }
            st[x].link = cur;
            last = cur;
        }

        // Propagate IDs
        int p = last;
        while (p != -1) {
            if (st[p].ids.empty() || st[p].ids.back() != id) st[p].ids.emplace_back(id), affected_states.emplace_back(p); else break;
            p = st[p].link;
        }
        return;
    }
    int cur = (int)st.size();
    st.emplace_back();
    st[cur].len = st[last].len + 1;

    int p = last;
    while (p != -1 && !has_next(p, c)) {
        set_next(p, c, cur);
        p = st[p].link;
    }
    if (p == -1) {
        st[cur].link = 0;
    } else {
        int q = get_next(p, c);
        if (st[p].len + 1 == st[q].len) {
            st[cur].link = q;
        } else {
            // clone q
            int clone = (int)st.size();
            st.emplace_back();
            st[clone].len = st[p].len + 1;
            for (auto e : st[q].next) {
                st[clone].next.push_back(e);
            }
            st[clone].link = st[q].link;
            for (auto old_id : st[q].ids) { // copy ids
                st[clone].ids.emplace_back(old_id);
            }
            cloned_states.emplace_back(clone, q);

            while (p != -1 && get_next(p, c) == q) {
                set_next(p, c, clone);
                p = st[p].link;
            }
            st[q].link = st[cur].link = clone;
        }
    }

    last = cur;
    p = last;
    while (p != -1) {
        if (st[p].ids.empty() || st[p].ids.back() != id) st[p].ids.emplace_back(id), affected_states.emplace_back(p); else break;
        p = st[p].link;
    }
}

void GeneralizedSuffixAutomaton::add_string(uint32_t id, const std::string &s) {
    // We'll add characters of s by extending the automaton while resetting 'last' at the start
    // so the string is added as a separate sequence (avoiding cross-string suffixes).
    last = 0;
    st[0].ids.emplace_back(id);
    affected_states.clear();
    cloned_states.clear();
    affected_states.emplace_back(0);
    for (char c : s) {
        if (c >= 'a' && c <= 'z') {
            sa_extend(c, id);
        }
        else {
            LOG_WARN("Non-alphabetic character '", c, "' in the ", id, "-th string: did you pre-process data correctly?");
        }
    }
}

int GeneralizedSuffixAutomaton::query(const std::string &p) const {
    int v = 0;
    for (char c : p) {
        int next = get_next(v, c);
        if (next == -1) return -1;
        v = next;
    }
    // v is the state representing all end positions of strings that contain p
    // return its stored IDs
    return v;
}

int GeneralizedSuffixAutomaton::size_tot() {
    int tot_size = 0;
    for (size_t i = 0; i < st.size(); ++i) {
        tot_size += st[i].ids.size();
    }
    return tot_size;
}

void GeneralizedSuffixAutomaton::print() const {
    std::cout << "GeneralizedSuffixAutomaton with " << st.size() << " states\n";
    for (size_t i = 0; i < st.size(); ++i) {
        const auto &state = st[i];
        std::cout << "State " << i << ": len=" << state.len << ", link=" << state.link << "\n";
        std::cout << "  transitions: ";
        for (const auto &t : state.next) {
            std::cout << "'" << t.c << "'->" << t.to << "  ";
        }
        std::cout << "\n";
        std::cout << "  ids: {";
        for (size_t j = 0; j < state.ids.size(); ++j) {
            std::cout << state.ids[j];
            if (j + 1 < state.ids.size()) std::cout << ", ";
        }
        std::cout << "}\n";
    }
}

std::vector<GeneralizedSuffixAutomaton::Statistics> GeneralizedSuffixAutomaton::get_statistics() const {
    std::vector<Statistics> stats;
    std::queue<std::pair<int, int>> q;
    q.emplace(0, 0); // state id, depth
    while (!q.empty()) {
        auto [state_id, depth] = q.front();
        q.pop();
        if (stats.size() <= static_cast<size_t>(depth)) {
            stats.emplace_back();
        }
        stats[depth].sizes.push_back(static_cast<int>(st[state_id].ids.size()));
        for (const auto &t : st[state_id].next) {
            q.emplace(t.to, depth + 1);
        }
    }
    for (auto &stat : stats) {
        std::sort(stat.sizes.begin(), stat.sizes.end());
        int n = static_cast<int>(stat.sizes.size());
        if (n % 2 == 1) {
            stat.mid = stat.sizes[n / 2];
        } else {
            stat.mid = (stat.sizes[n / 2 - 1] + stat.sizes[n / 2]) / 2.0;
        }
        double sum = 0.0;
        for (int size : stat.sizes) {
            sum += size;
        }
        stat.avg = sum / n;
    }
    return stats;
}

std::vector<int> GeneralizedSuffixAutomaton::topo_sort() const {
    int n = static_cast<int>(st.size());
    int* in_degree = new int[n];
    for (int i = 0; i < n; ++i) {
        in_degree[i] = 0;
    }
    for (int i = 0; i < n; ++i) {
        for (const auto &t : st[i].next) {
            in_degree[t.to]++;
        }
    }
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (in_degree[i] == 0) {
            q.push(i);
        }
    }
    std::vector<int> order;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);
        for (const auto &t : st[u].next) {
            int v = t.to;
            in_degree[v]--;
            if (in_degree[v] == 0) {
                q.push(v);
            }
        }
    }
    // Bug check
    for (int i = 0; i < n; i++) {
        if (in_degree[i] != 0) {
            LOG_ERROR("Cycle detected in GSA states!");
        }
    }
    delete [] in_degree;
    return order;
}

void GeneralizedSuffixAutomaton::build_reverse() {
    if (deg) delete [] deg;
    if (reverse_next) delete [] reverse_next;
    deg = new std::atomic<int>[st.size()];
    reverse_next = new std::vector<uint32_t>[st.size()];
    for (int i = 0; i < st.size(); i++) {
        deg[i] = st[i].next.size();
        for (auto e : st[i].next) {
            reverse_next[e.to].emplace_back(i);
        }
    }
}

void GeneralizedSuffixAutomaton::release_reverse() {
    if (deg) {
        delete [] deg;
        deg = nullptr;
    }
    if (reverse_next) {
        delete [] reverse_next;
        reverse_next = nullptr;
    }
}

void GeneralizedSuffixAutomaton::shrink_to_fit() {
    for (auto& state : st) {
        state.ids.shrink_to_fit();
    }
    st.shrink_to_fit();
}

void GeneralizedSuffixAutomaton::dump(char* output_file) {
    std::ofstream f(output_file);
    f << st.size() << "\n";
    for (int i = 0; i < st.size(); i++) {
        f << st[i].len << " " << st[i].link << " " << st[i].next.size() << " " << st[i].ids.size() << "\n";
        for (auto e : st[i].next) {
            f << int(e.c) << " " << e.to << " ";
        }
        f << "\n";
        for (auto id : st[i].ids) {
            f << id << " ";
        }
        f << "\n";
    }
    f.close();
}
